INSERT INTO `news_sentiment` (`id`, `ts_code`, `pub_date`, `title`, `content`, `sentiment_score`, `sentiment_label`, `source`) VALUES (7, '000001.SZ', '2026-05-25 20:32:00', '银行股大分化：建行股价创新高，股份行普跌，城商行“独霸”四强', '股息率方面，iFinD数据显示，截至5月25日，华夏银行（600015.SH）、兴业银行股息率（TTM）超6%，上海银行（601229.SH）、光大银行（601818.SH）、平安银行（000001.SZ）、招商银行（600036.SH）等11家银行股息率（TTM）在5%的水平。', '0.3652', '负面', '界面新闻');
