INSERT INTO `news_sentiment` (`id`, `ts_code`, `pub_date`, `title`, `content`, `sentiment_score`, `sentiment_label`, `source`) VALUES (11, '000063.SZ', '2026-05-28 16:26:55', '中兴通讯000063龙虎榜数据05-28)', '交易所2026年5月28日公布的交易公开信息显示，中兴通讯因成为日涨幅偏离值达到7%的前5只证券上榜。中兴通讯当日收报38.3元，涨跌幅9.99%，偏离值9.12%，换手率5.53%，成交额81.63亿。 免责声明：本文基于AI生产，仅供参考，不构成任何投资建议，据此操作风险自担。', '0.5679', '中性', '东方财富Choice数据');
INSERT INTO `news_sentiment` (`id`, `ts_code`, `pub_date`, `title`, `content`, `sentiment_score`, `sentiment_label`, `source`) VALUES (12, '000063.SZ', '2026-05-28 08:41:00', '中兴通讯首次回购1926万股 金额6.7亿元', '5月28日，中兴通讯（000063/00763）发布公告，2026年5月27日首次回购A股股份1926万股，占总股本的0.40%，回购金额为6.7亿元，成交价格区间为34.44元/股至34.98元/股。', '0.0302', '负面', '财中社');
INSERT INTO `news_sentiment` (`id`, `ts_code`, `pub_date`, `title`, `content`, `sentiment_score`, `sentiment_label`, `source`) VALUES (13, '000063.SZ', '2026-05-28 17:08:00', '5月28日龙虎榜净买入额前10个股', '南财智讯5月28日电，盘后数据显示，因当日异动登上龙虎榜的个股中，资金净买入最多的前三位分别是云南锗业(002428.SZ)、中兴通讯000063.SZ)与联特科技(301205.SZ)。其中排名第一的云南锗业净买额达9.79亿元，占总成交金额的12.58%。', '0.0559', '负面', '南方财经网');
INSERT INTO `news_sentiment` (`id`, `ts_code`, `pub_date`, `title`, `content`, `sentiment_score`, `sentiment_label`, `source`) VALUES (14, '000063.SZ', '2026-05-28 19:21:00', '9.79亿资金抢筹云南锗业，机构狂买华虹公司丨龙虎榜', '北向资金净买入金额最多的是中兴通讯（000063.SZ），净买入3.21亿元，占总成交金额的3.93%。净卖出金额最多的是华虹公司（688347.SH），为2.69亿元，占总成交金额的2.55%，当日收盘上涨15.79%，换手率为10.7%。', '0.9846', '正面', '21世纪经济报道');
